"""
Data Generator for Pokemon Mezastar Database
Full Authoritative 70-Card Sets across all Official Series (Galaxy 2, Galaxy 1, Stardust 4, Stardust 3, Stardust 2, Stardust 1, Special)
Directly synchronized with Taiwan Mezastar official database.
"""

from typing import List, Dict, Any, Optional

def calculate_defensive_profile(types: List[str]):
    from mezastar_data import TYPE_CHART
    weaknesses = []
    resistances = []
    immunities = []
    
    for atk_t, mults in TYPE_CHART.items():
        total_mult = 1.0
        for def_t in types:
            total_mult *= mults.get(def_t, 1.0)
        
        if total_mult >= 2.0:
            weaknesses.append(f"{atk_t} ({total_mult}x)")
        elif total_mult == 0.0:
            immunities.append(f"{atk_t} (0.0x)")
        elif total_mult < 1.0:
            resistances.append(f"{atk_t} ({total_mult}x)")
            
    return weaknesses, resistances, immunities

def create_card_full(
    cid: str, name: str, series: str, star: int, energy: int, types: List[str],
    hp: int, atk: int, defense: int, sp_atk: int, sp_def: int, speed: int,
    move_name: str, move_type: str, move_power: int,
    sec_move: Optional[Dict[str, Any]] = None,
    special_tags: Optional[List[str]] = None,
    img_slug: str = "pikachu"
) -> Dict[str, Any]:
    special_tags = special_tags or []
    weaknesses, resistances, immunities = calculate_defensive_profile(types)
    
    has_mega = "超級進化" in special_tags or "Mega進化" in special_tags
    has_z_move = "Z招式" in special_tags
    has_dynamax = "極巨化" in special_tags
    has_gigantamax = "超極巨化" in special_tags
    has_double_attack = "雙重招式" in special_tags or "雙重衝刺" in special_tags or "雙重攻擊" in special_tags
    has_combo_tag = "組合招式" in special_tags or "組合卡匣" in special_tags
    has_chain_attack = "連擊" in special_tags or "連擊卡匣" in special_tags
    has_terastal = "太晶化" in special_tags
    has_primal = "原始回歸" in special_tags

    primary_special = special_tags[0] if special_tags else "無"

    return {
        "id": cid,
        "name": name,
        "series": series,
        "star": star,
        "energy": energy,
        "types": types,
        "hp": hp,
        "atk": atk,
        "def": defense,
        "sp_atk": sp_atk,
        "sp_def": sp_def,
        "spd": speed,
        "move_name": move_name,
        "move_type": move_type,
        "move_power": move_power,
        "second_move": sec_move or {},
        "special": primary_special,
        "special_mechanics": special_tags,
        "has_mega": has_mega,
        "has_z_move": has_z_move,
        "has_dynamax": has_dynamax,
        "has_gigantamax": has_gigantamax,
        "has_double_attack": has_double_attack,
        "has_combo_tag": has_combo_tag,
        "has_chain_attack": has_chain_attack,
        "has_terastal": has_terastal,
        "has_primal": has_primal,
        "weaknesses": weaknesses,
        "resistances": resistances,
        "immunities": immunities,
        "image": f"https://img.pokemondb.net/sprites/home/normal/{img_slug}.png"
    }

